CREATE TABLE IF NOT EXISTS `coa_dungeon_rescale_budget` (
    `map_id` SMALLINT UNSIGNED NOT NULL,
    `difficulty` TINYINT UNSIGNED NOT NULL,
    `entry` INT UNSIGNED NOT NULL,
    `level` TINYINT UNSIGNED NOT NULL,
    `health` INT UNSIGNED NOT NULL,
    `melee_multiplier` FLOAT NOT NULL,
    `spell_multiplier` FLOAT NOT NULL,
    `attack_time` INT UNSIGNED NOT NULL,
    `ranged_attack_time` INT UNSIGNED NOT NULL,
    PRIMARY KEY (`map_id`, `difficulty`, `entry`)
) ENGINE=InnoDB;

DELETE FROM `coa_dungeon_rescale_budget` WHERE `map_id` IN (545, 546, 547);
